using System;
using System.Collections;
using System.IO;
using System.Linq;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
public sealed class OrdinaryNodeEnemiesTests {
 static object Get(object value,string name){var p=value.GetType().GetProperty(name);Assert.NotNull(p,"Missing typed enemy consumer: "+name);return p.GetValue(value);}
 static (OrdinaryFiveStartInput Start,BRouteCommand Command,JObject Response) Fixture(){
  var f=OrdinaryNodeStartWireTests.Fixture();var parsed=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command);var scale=parsed.Scaling;var profile=f.Command.Binding.Capture()["pendingNode"]["encounterDefinition"];
  f.Response["receipt"]["nodeStart"]["snapshot"]["runtime"]["enemies"]=new JObject{["version"]="ordinary.node-enemies.v1.20261031",["scalingBindingHash"]=scale.BindingHash,["actionDefinition"]=profile["enemies"]["definition"].DeepClone(),["gunners"]=new JArray(scale.IssuedGunnerIds.Select(id=>new JObject{["instanceId"]=id,["hp"]=scale.GunnerHp.Snapshot(),["maxHp"]=scale.GunnerHp.Snapshot(),["defense"]=profile["enemies"]["defense"].DeepClone(),["rawDamage"]=scale.GunnerRawDamage.Snapshot()})),["artillery"]=new JObject{["hazardId"]=scale.IssuedHazardId,["hp"]=scale.LauncherHp.Snapshot(),["maxHp"]=scale.LauncherHp.Snapshot(),["rawDamage"]=scale.ArtilleryRawDamage.Snapshot(),["definition"]=profile["artillery"].DeepClone(),["minimumThreatClearToPreviewMs"]=profile["minimumThreatClearToPreviewMs"].DeepClone(),["previewRequires"]=profile["previewRequires"].DeepClone()}};
  Pin(f.Response);return f;
 }
 static void Pin(JObject response){var node=response["receipt"]["nodeStart"];node["snapshotHash"]=BDirectAttackInput.Digest(node["snapshot"]).Substring(7);}
 static (OrdinaryFiveStartInput Start,BRouteCommand Command,JObject Response) SpatialFixture(){var f=Fixture();var scale=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).Scaling;var enemies=f.Response["receipt"]["nodeStart"]["snapshot"]["runtime"]["enemies"];enemies["version"]="ordinary.node-enemies.v2.20261031";enemies["spatial"]=new JObject{["physicalInstanceId"]=scale.IssuedEnemyTrainId,["definition"]=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/ReferenceDefinitions809/definitions.json"))["definitions"]["enemySpatial"].DeepClone()};Pin(f.Response);return f;}
 [Test] public void V2ConsumesSameArrivalSpatialDefinitionAndKeepsMissingMuzzleExplicit(){var f=SpatialFixture();var result=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command);Assert.NotNull(result.NodeStart.Enemies,"V2 needs an actual node consumer");result.NodeStart.RequireOriginal(f.Start);var spatial=Get(result.NodeStart.Enemies,"Spatial");Assert.NotNull(spatial);Assert.AreEqual(result.Scaling.IssuedEnemyTrainId,Get(spatial,"PhysicalInstanceId"));var definition=(JObject)spatial.GetType().GetMethod("CaptureDefinition").Invoke(spatial,null);Assert.IsTrue(JToken.DeepEquals(f.Response["receipt"]["nodeStart"]["snapshot"]["runtime"]["enemies"]["spatial"]["definition"],definition));Assert.AreEqual((string)definition["definitionHash"],Get(spatial,"DefinitionHash"));Assert.AreEqual((string)definition["geometry"]["definitionHash"],Get(spatial,"GeometryDefinitionHash"));Assert.AreEqual(JTokenType.Null,definition["muzzle"].Type);Assert.AreEqual(JTokenType.Null,definition["hitVolume"].Type);Assert.IsFalse((bool)definition["executionVerified"]);Assert.IsFalse(result.NodeStart.CanStart);definition["muzzle"]=new JArray(0,0,0);Assert.AreEqual(JTokenType.Null,((JObject)spatial.GetType().GetMethod("CaptureDefinition").Invoke(spatial,null))["muzzle"].Type);var output=Environment.GetEnvironmentVariable("LASTRAIL_ENEMY_V2_FIXTURE_PATH");if(!string.IsNullOrEmpty(output)){var path=Path.GetFullPath(output);if(!path.StartsWith(Path.GetFullPath("D:/Project/LASTRAIL/QA/"),StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Enemy fixture output must stay inside project QA.");File.WriteAllText(path,new JObject{["scope"]="SYNTHETIC_CONTRACT_FIXTURE_NOT_SERVER_RUN",["binding"]=f.Command.Binding.Capture(),["command"]=f.Command.Capture()["command"],["response"]=f.Response}.ToString());}}
 [TestCase("missing")][TestCase("null")][TestCase("extra")][TestCase("identity")][TestCase("definition")][TestCase("geometry")][TestCase("anchor")][TestCase("muzzle")][TestCase("verified")][TestCase("downgrade")][TestCase("binding")]
 public void V2RejectsRehashedSpatialSubstitutionAndVersionDowngrade(string fault){var f=SpatialFixture();var enemies=f.Response["receipt"]["nodeStart"]["snapshot"]["runtime"]["enemies"];var spatial=(JObject)enemies["spatial"];var d=(JObject)spatial["definition"];switch(fault){case "missing":((JObject)enemies).Remove("spatial");break;case "null":enemies["spatial"]=null;break;case "extra":spatial["generation"]=1;break;case "identity":spatial["physicalInstanceId"]=new string('1',32);break;case "definition":spatial["definition"]=null;break;case "geometry":d["geometry"]["lengthMm"]=12001;break;case "anchor":d["placement"]["footAnchorYmm"]=3214;break;case "muzzle":d["muzzle"]=new JArray(0,0,0);break;case "verified":d["executionVerified"]=true;break;case "downgrade":enemies["version"]="ordinary.node-enemies.v1.20261031";break;case "binding":enemies["scalingBindingHash"]=new string('0',64);break;}if(fault=="geometry"||fault=="anchor"||fault=="muzzle"||fault=="verified"){d.Remove("definitionHash");d["definitionHash"]=BDirectAttackInput.Digest(d).Substring(7);}Pin(f.Response);Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,f.Response.ToString(),f.Command));}
 [Test] public void StoredV1WithSpatialCapableProfileIsNotUpgraded(){var f=Fixture();var node=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart;Assert.NotNull(node.Enemies);Assert.IsNull(Get(node.Enemies,"Spatial"));Assert.AreEqual("ordinary.node-enemies.v1.20261031",(string)node.Capture()["snapshot"]["runtime"]["enemies"]["version"]);}
 [Test] public void V2RestartRetainsSameSpatialOwnerAndOriginalDefinition(){var f=SpatialFixture();var node=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart;Assert.NotNull(node.Enemies);var spatial=Get(node.Enemies,"Spatial");var request=new OrdinaryNodeRestart(node,"spatial-restart",node.EntryMapRevision,node.Generation);var response=new JObject{["accepted"]=true,["version"]="ordinary.node-restart.v1.20261028",["requestId"]=request.Key,["accountId"]=node.AccountId,["runId"]=node.RunId,["nodeId"]=node.NodeId,["status"]="RESTARTED",["revision"]=node.EntryMapRevision+1,["generation"]=node.Generation+1,["snapshot"]=node.Capture()["snapshot"],["snapshotHash"]=node.SnapshotHash};Assert.AreSame(spatial,Get(request.ReadResponse(response.ToString()).Start.Enemies,"Spatial"));}
 [Test] public void ArrivalConsumesIssuedEnemyInputsWithoutPromotingCombatReadiness(){var f=Fixture();var result=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command);result.NodeStart.RequireOriginal(f.Start);var enemies=Get(result.NodeStart,"Enemies");Assert.NotNull(enemies);Assert.AreEqual(result.Scaling.BindingHash,Get(enemies,"ScalingBindingHash"));var rows=((IEnumerable)Get(enemies,"Gunners")).Cast<object>().ToArray();Assert.AreEqual(2,rows.Length);Assert.AreEqual(result.Scaling.IssuedGunnerIds[0],Get(rows[0],"InstanceId"));Assert.IsTrue(JToken.DeepEquals(result.Scaling.GunnerHp.Snapshot(),((CombatExactValue)Get(rows[0],"Hp")).Snapshot()));Assert.IsTrue(JToken.DeepEquals(result.Scaling.GunnerRawDamage.Snapshot(),((CombatExactValue)Get(rows[0],"RawDamage")).Snapshot()));Assert.AreEqual(result.Scaling.IssuedHazardId,Get(Get(enemies,"Artillery"),"HazardId"));Assert.IsFalse(result.NodeStart.CanStart);var original=(JObject)enemies.GetType().GetMethod("CaptureActionDefinition").Invoke(enemies,null);var copy=(JObject)enemies.GetType().GetMethod("CaptureActionDefinition").Invoke(enemies,null);copy["basicPeriodMs"]=1;Assert.IsTrue(JToken.DeepEquals(original,(JToken)enemies.GetType().GetMethod("CaptureActionDefinition").Invoke(enemies,null)));}
 [TestCase("binding")][TestCase("identity")][TestCase("order")][TestCase("hp")][TestCase("damage")][TestCase("defense")][TestCase("action")][TestCase("hazard")][TestCase("artillery")][TestCase("preview")][TestCase("extra")][TestCase("scale-missing")]
 public void RehashedForeignOrRescaledEnemyInputsCannotReachNodeOwner(string fault){var f=Fixture();var p=f.Response["receipt"]["nodeStart"]["snapshot"]["runtime"]["enemies"];switch(fault){case "binding":p["scalingBindingHash"]=new string('0',64);break;case "identity":p["gunners"][0]["instanceId"]="foreign";break;case "order":var first=p["gunners"][0].DeepClone();p["gunners"][0]=p["gunners"][1].DeepClone();p["gunners"][1]=first;break;case "hp":p["gunners"][0]["hp"]["numerator"]="1";break;case "damage":p["gunners"][0]["rawDamage"]["numerator"]="1";break;case "defense":p["gunners"][0]["defense"]=0;break;case "action":p["actionDefinition"]["basicPeriodMs"]=1;break;case "hazard":p["artillery"]["hazardId"]="foreign";break;case "artillery":p["artillery"]["definition"]["flightMs"]=1;break;case "preview":p["artillery"]["previewRequires"]=new JArray();break;case "extra":p["fallback"]=false;break;case "scale-missing":((JObject)f.Response["receipt"]).Remove("firstPlayableScaling");break;}Pin(f.Response);Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,f.Response.ToString(),f.Command));}
 [Test] public void HistoricalEnemyAbsenceRemainsUnavailable(){var f=OrdinaryNodeStartWireTests.Fixture();Assert.IsNull(Get(BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart,"Enemies"));}
 [Test] public void RestartReusesExactEnemyOwnerWithoutReissuingIds(){var f=Fixture();var node=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart;var enemies=Get(node,"Enemies");var request=new OrdinaryNodeRestart(node,"enemy-restart",node.EntryMapRevision,node.Generation);var response=new JObject{["accepted"]=true,["version"]="ordinary.node-restart.v1.20261028",["requestId"]=request.Key,["accountId"]=node.AccountId,["runId"]=node.RunId,["nodeId"]=node.NodeId,["status"]="RESTARTED",["revision"]=node.EntryMapRevision+1,["generation"]=node.Generation+1,["snapshot"]=node.Capture()["snapshot"],["snapshotHash"]=node.SnapshotHash};Assert.AreSame(enemies,Get(request.ReadResponse(response.ToString()).Start,"Enemies"));}
}
